	const INJECTED_MANIFEST = {"manifest_version":3,"name":"Random User Agent","version":"4.3","description":"Generate random user agent with chrome extension. Switch browser agents to any device or browser. Perfect for testing and privacy","permissions":["activeTab","alarms","storage","scripting","declarativeNetRequest"],"optional_permissions":[],"content_scripts":[],"options_ui":{},"browser_action":{},"page_action":{},"action":{"default_popup":"popup/index.html","default_icon":{"16":"assets/icons/16-green.png","32":"assets/icons/32-green.png","48":"assets/icons/48-green.png","128":"assets/icons/128-green.png"}},"icons":{"16":"assets/icons/16-green.png","32":"assets/icons/32-green.png","48":"assets/icons/48-green.png","128":"assets/icons/128-green.png"},"web_accessible_resources":[{"resources":["/inject.js"],"matches":["<all_urls>"]}],"background":{"service_worker":"background.js","type":"module"},"_id":"random-user-agent"};
